[CmdletBinding()]
param(
    [Parameter(Mandatory = $true)]
    [ValidateSet('EditMode', 'PlayMode', 'All')]
    [string] $TestPlatform,

    [string] $UnityEditorPath = $env:UNITY_EDITOR_PATH,
    [string] $ProjectPath = [System.IO.Path]::GetFullPath((Join-Path $PSScriptRoot '..\..')),
    [string] $DataRoot = $env:DIGGLES_DATA_ROOT
)

$ErrorActionPreference = 'Stop'

if ([string]::IsNullOrWhiteSpace($UnityEditorPath)) {
    # Default to the Unity Hub install of the project's editor version.
    $version = (Get-Content (Join-Path $ProjectPath 'ProjectSettings\ProjectVersion.txt') | Select-String '^m_EditorVersion: (.+)$').Matches[0].Groups[1].Value.Trim()
    $UnityEditorPath = Join-Path ${env:ProgramFiles} "Unity\Hub\Editor\$version\Editor\Unity.exe"
}
if ([string]::IsNullOrWhiteSpace($DataRoot)) {
    throw "Set DIGGLES_DATA_ROOT or pass -DataRoot with the legally obtained original Diggles data directory."
}

$UnityEditorPath = [System.IO.Path]::GetFullPath($UnityEditorPath)
$ProjectPath = [System.IO.Path]::GetFullPath($ProjectPath)
$DataRoot = [System.IO.Path]::GetFullPath($DataRoot)

if (-not (Test-Path -LiteralPath $UnityEditorPath -PathType Leaf)) {
    throw "Unity editor was not found at '$UnityEditorPath'."
}
if (-not (Test-Path -LiteralPath (Join-Path $ProjectPath 'ProjectSettings\ProjectVersion.txt') -PathType Leaf)) {
    throw "'$ProjectPath' is not a Unity project."
}
$testPlatforms = if ($TestPlatform -eq 'All') { @('EditMode', 'PlayMode') } else { @($TestPlatform) }
& (Join-Path $PSScriptRoot 'test-original-data.ps1') -DataRoot $DataRoot

$artifactDirectory = Join-Path $ProjectPath 'artifacts\unity-tests'
New-Item -ItemType Directory -Path $artifactDirectory -Force | Out-Null

# The editor resolves this project-root override before the shipped StreamingAssets config.
$configPath = Join-Path $ProjectPath 'diggles_config.json'
$hadConfig = Test-Path -LiteralPath $configPath -PathType Leaf
$previousConfig = if ($hadConfig) { Get-Content -LiteralPath $configPath -Raw } else { $null }
$normalizedDataRoot = $DataRoot.Replace('\', '/')
$config = [ordered]@{
    _comment = 'Temporary headless-test override generated by run-unity-tests.ps1.'
    dataRoot = $normalizedDataRoot
    locale = ''
} | ConvertTo-Json

try {
    [System.IO.File]::WriteAllText($configPath, $config, [System.Text.UTF8Encoding]::new($false))

    $failures = [System.Collections.Generic.List[string]]::new()
    foreach ($platform in $testPlatforms) {
        $resultPath = Join-Path $artifactDirectory "$($platform.ToLowerInvariant())-results.xml"
        $logPath = Join-Path $artifactDirectory "$($platform.ToLowerInvariant())-unity.log"
        Remove-Item -LiteralPath $resultPath, $logPath -Force -ErrorAction SilentlyContinue

        try {
            $previousDataRoot = $env:DIGGLES_DATA_ROOT
            $env:DIGGLES_DATA_ROOT = $DataRoot
            $arguments = @(
                '-batchmode'
                '-nographics'
                '-projectPath', "`"$ProjectPath`""
                '-runTests'
                '-testPlatform', $platform
                '-testResults', "`"$resultPath`""
                '-logFile', "`"$logPath`""
            )
            $process = Start-Process -FilePath $UnityEditorPath -ArgumentList $arguments `
                -Wait -PassThru -WindowStyle Hidden

            if (-not (Test-Path -LiteralPath $resultPath -PathType Leaf)) {
                if (Test-Path -LiteralPath $logPath -PathType Leaf) {
                    Get-Content -LiteralPath $logPath -Tail 200
                }
                throw "Unity did not produce a $platform result file (exit code $($process.ExitCode))."
            }

            [xml] $results = Get-Content -LiteralPath $resultPath -Raw
            $run = $results.'test-run'
            if ($null -eq $run) {
                throw "Unity produced an invalid NUnit result at '$resultPath'."
            }

            Write-Host ("{0}: total={1}, passed={2}, failed={3}, skipped={4}, inconclusive={5}, duration={6}s" -f `
                $platform, $run.total, $run.passed, $run.failed, $run.skipped, $run.inconclusive, $run.duration)

            if ([int] $run.failed -gt 0 -or $process.ExitCode -ne 0) {
                $failedTests = Select-Xml -Xml $results -XPath "//test-case[@result='Failed']"
                foreach ($failedTest in $failedTests) {
                    Write-Host "FAILED: $($failedTest.Node.fullname)"
                }
                $failures.Add("$platform (Unity exit code $($process.ExitCode), failed tests $($run.failed))")
            }
        }
        catch {
            $failures.Add("$platform ($($_.Exception.Message))")
            Write-Warning "$platform test execution failed: $($_.Exception.Message)"
        }
        finally {
            $env:DIGGLES_DATA_ROOT = $previousDataRoot
        }
    }

    if ($failures.Count -gt 0) {
        throw "Unity test failures: $($failures -join '; ')"
    }
}
finally {
    if ($hadConfig) {
        [System.IO.File]::WriteAllText($configPath, $previousConfig, [System.Text.UTF8Encoding]::new($false))
    }
    else {
        Remove-Item -LiteralPath $configPath -Force -ErrorAction SilentlyContinue
    }
}
